<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">多元线性回归</h1><p class="hero-desc">建立 ŷ = b₀ + b₁x₁ + b₂x₂ + ... 的多元线性回归方程，通过最小二乘法求解回归系数，计算 R²、调整 R² 和 F 检验，输出回归系数表</p></div><el-tag class="hero-tag" effect="dark" round>REGRESSION · MULTIPLE</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-form-item label="数据（每行一条记录，最后一列为Y，前面列为X变量）"><el-input v-model="form.rawData" type="textarea" :rows="6" placeholder="x1,x2,...,y" /></el-form-item></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">回归方程</div><div class="formula-box">ŷ = b₀ + b₁x₁ + b₂x₂ + ...</div></div><div class="principle-block"><div class="principle-label">F 检验</div><p>H₀: β₁ = β₂ = ... = 0</p></div><div class="principle-block"><div class="principle-label">数据格式</div><p>每行一条观测，最后一列为因变量 Y</p></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p><p class="ref-item">[2] Draper NR, Smith H. Applied Regression Analysis, 1998.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section">
      <div class="metrics-grid mb-5"><div v-for="m in metrics" :key="m.label" class="metric-card" :class="m.type"><div class="metric-indicator" /><div class="metric-label">{{ m.label }}</div><div class="metric-value">{{ m.value }}</div></div></div>
      <el-card shadow="never" class="detail-card mb-4"><template #header><div class="card-header-inner"><el-icon class="header-icon"><Document /></el-icon><span class="font-bold">回归系数</span></div></template><el-table :data="coefRows" size="small" stripe border><el-table-column prop="name" label="变量" width="80" /><el-table-column prop="coef" label="系数" /><el-table-column prop="se" label="SE" /><el-table-column prop="t" label="t" /><el-table-column prop="p" label="P" /></el-table></el-card>
    </div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, Document } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "RegMultiple" }); const form = reactive({ rawData: "" }); const res = ref(false); const metrics = ref<any[]>([]); const coefRows = ref<any[]>([]);
function loadDemo() { form.rawData = "1,2,5.1\n2,3,7.8\n3,1,6.2\n4,4,12.1\n5,2,9.5\n6,5,15.3\n7,3,13.0\n8,6,18.2\n9,4,16.1\n10,7,21.5"; calculate(); }
function clearAll() { form.rawData = ""; res.value = false; }
function calculate() {
  const rows = form.rawData.trim().split("\n").map(l => S.parseNumbers(l)); const n = rows.length, p = (rows[0]?.length || 2) - 1;
  if (n < p + 2 || p < 1) { ElMessage.warning("数据不足"); return; }
  const y = rows.map(r => r[r.length - 1]); const X = rows.map(r => [1, ...r.slice(0, p)]); const cols = p + 1;
  const XtX: number[][] = Array.from({ length: cols }, () => Array(cols).fill(0)); const Xty: number[] = Array(cols).fill(0);
  for (let i = 0; i < n; i++) { for (let j = 0; j < cols; j++) { Xty[j] += X[i][j] * y[i]; for (let k = 0; k < cols; k++) XtX[j][k] += X[i][j] * X[i][k]; } }
  const aug = XtX.map((row, i) => [...row, Xty[i]]);
  for (let i = 0; i < cols; i++) { let maxRow = i; for (let k = i + 1; k < cols; k++) { if (Math.abs(aug[k][i]) > Math.abs(aug[maxRow][i])) maxRow = k; } [aug[i], aug[maxRow]] = [aug[maxRow], aug[i]]; if (Math.abs(aug[i][i]) < 1e-12) continue; for (let k = i + 1; k < cols; k++) { const f = aug[k][i] / aug[i][i]; for (let j = i; j <= cols; j++) aug[k][j] -= f * aug[i][j]; } }
  const beta = Array(cols).fill(0); for (let i = cols - 1; i >= 0; i--) { beta[i] = aug[i][cols]; for (let j = i + 1; j < cols; j++) beta[i] -= aug[i][j] * beta[j]; beta[i] /= aug[i][i] || 1; }
  const yHat = X.map(xi => xi.reduce((s, v, j) => s + v * beta[j], 0)); const my = S.mean(y);
  const SST = y.reduce((s, yi) => s + (yi - my) ** 2, 0); const SSRes = y.reduce((s, yi, i) => s + (yi - yHat[i]) ** 2, 0); const SSReg = SST - SSRes;
  const R2 = SST > 0 ? 1 - SSRes / SST : 0; const adjR2 = 1 - (SSRes / (n - p - 1)) / (SST / (n - 1));
  const F = (SSReg / p) / (SSRes / (n - p - 1) || 1); const pF = S.fTestPValue(F, p, n - p - 1); const sig = pF < 0.05; res.value = true;
  metrics.value = [{ label: "n", value: n, type: "accent" }, { label: "变量数", value: p, type: "accent" }, { label: "R²", value: S.fmt(R2), type: "success" }, { label: "调整R²", value: S.fmt(adjR2), type: "success" }, { label: "F", value: S.fmt(F), type: "warning" }, { label: "P", value: S.fmtP(pF), type: sig ? "warning" : "neutral" }];
  coefRows.value = beta.map((b, i) => ({ name: i === 0 ? "截距" : `X${i}`, coef: S.fmt(b), se: "-", t: "-", p: "-" }));
}
</script>
